import{_ as t,o,c as d,ag as a}from"./chunks/framework.BaNuf0sO.js";const g=JSON.parse('{"title":"AiSenderHeader（内部件 · 仅 API）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/agent/src/components/sender/docs/README-AiSenderHeader.md","filePath":"docs/agent/src/components/sender/docs/README-AiSenderHeader.md"}'),r={name:"docs/agent/src/components/sender/docs/README-AiSenderHeader.md"};function s(i,e,c,n,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="aisenderheader-内部件-·-仅-api" tabindex="-1">AiSenderHeader（内部件 · 仅 API） <a class="header-anchor" href="#aisenderheader-内部件-·-仅-api" aria-label="Permalink to &quot;AiSenderHeader（内部件 · 仅 API）&quot;">​</a></h1><blockquote><p>内部件，[MUST NOT] 当公共组件用（无独立对外使用场景）。AiDialogue 新会话态经 <code>#header</code> 插槽渲染：空态欢迎语（logo + 问候）+ 快捷问题卡（2 列网格，<strong>点选即发送</strong>；窄容器降单列）。</p></blockquote><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ 以组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>greeting</code></td><td><code>string?</code></td><td>见下</td><td>欢迎语文案</td></tr><tr><td><code>swiftAsk</code></td><td><code>string[]?</code></td><td>—</td><td>快捷问题；空/不传 → <strong>整块建议卡不渲染</strong></td></tr><tr><td><code>logoUrl</code></td><td><code>string?</code></td><td>—</td><td>logo 图片地址（优先级 <code>#logo</code> 槽 &gt; logoUrl &gt; <strong>不渲染</strong>）</td></tr></tbody></table><p><code>greeting</code> 缺省值在本组件内解析（AiDialogue 只透传、不预填）：有 <code>swiftAsk</code> → <code>你可以这么问：</code>；无 → <code>今天有什么可以帮到你？</code></p><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><p>无</p><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>槽</th><th>scope</th><th>语义</th></tr></thead><tbody><tr><td><code>#logo</code></td><td><code>{ size: string, mode: &quot;ai&quot; }</code></td><td>logo 渲染口（默认 img；无 logoUrl 且无槽 → 不渲染）</td></tr></tbody></table><h3 id="expose" tabindex="-1">Expose <a class="header-anchor" href="#expose" aria-label="Permalink to &quot;Expose&quot;">​</a></h3><p>无</p><h2 id="视觉取向-0-3-0" tabindex="-1">视觉取向（0.3.0） <a class="header-anchor" href="#视觉取向-0-3-0" aria-label="Permalink to &quot;视觉取向（0.3.0）&quot;">​</a></h2><p><strong>极简 / 克制</strong>——靠留白与字重分层，不靠描边与色块（甲方定调「简洁为主，不要太华丽花哨」）。建议卡的调整<strong>只做减量、零新 token</strong>：</p><table tabindex="0"><thead><tr><th>项</th><th>0.2.0</th><th>0.3.0</th><th>为什么</th></tr></thead><tbody><tr><td>底 / 边</td><td>透明底 + <code>1px --dc-agent-border</code></td><td><code>--dc-agent-bubble-bg</code> 浅底 + 无边</td><td>三条并排描边在窄侧栏里形成栅栏感；浅底与输入框 / 用户气泡同料，归为同一族</td></tr><tr><td>hover</td><td>底变色</td><td><strong>加边框</strong>（底不变）</td><td>反馈由「变色」改为「显形」，静态更安静</td></tr><tr><td>圆角</td><td><code>radius-lg</code> 12px</td><td><code>radius</code> 6px</td><td>12px 在 246px 宽的长条上过圆润</td></tr><tr><td>字号</td><td>正文 16px</td><td><code>font-size-sm</code> 13px</td><td>与欢迎语（18px bold）拉开层次，避免读作「三个表单控件」</td></tr></tbody></table><p>节奏（在 <code>AiDialogue</code> 的 <code>.ai-dialogue-sender-header</code> 上）：<strong>横向内边距归零</strong>（原 10px 让卡片比输入框窄一圈、左右缘对不齐）+ <strong>底部 <code>space-6</code>(24px)</strong>（原 10px 与卡间距 8px 几乎相等，四个同色浅底块连成一片）。</p><h2 id="视觉修订-q21yfk-判据-8-·-对标豆包" tabindex="-1">视觉修订（q21yfk 判据 8 · 对标豆包） <a class="header-anchor" href="#视觉修订-q21yfk-判据-8-·-对标豆包" aria-label="Permalink to &quot;视觉修订（q21yfk 判据 8 · 对标豆包）&quot;">​</a></h2><ul><li><strong>建议卡 chips 化</strong>：撑满网格的灰方块 → 自适应宽度描边 chips（<code>inline-flex</code> 流式换行、发丝边 + 透明底、圆角上调），hover 浅底显形——「三条可点的建议」而非「三个禁用输入框」；窄容器仍靠流式换行自适应（容器查询降列随之退役）</li><li><strong>欢迎语字阶上调</strong>：<code>font-size-lg</code>(18px) → <code>font-size-xl</code>(22px，新 token，见批次 D7：不取豆包 28px，agent-ui 常嵌窄浮层/侧栏）</li></ul><h2 id="机制契约" tabindex="-1">机制契约 <a class="header-anchor" href="#机制契约" aria-label="Permalink to &quot;机制契约&quot;">​</a></h2><ul><li>快捷问题按钮 <code>@click</code> 调 <code>useAiSessionInject().sessionExpose.ask({ value })</code>——依赖 AiDialogue 经 <code>useAiSessionProvide</code> 注入的当前会话 expose；脱离对话上下文会拿到 undefined（按钮静默无效）</li><li><strong>降列走容器查询</strong>（<code>@container (max-width: 480px)</code>，容器上下文由 <code>.ai-dialogue</code> 的 <code>container-type: inline-size</code> 建立），[MUST NOT] 改回 <code>@media</code>——侧栏内嵌时视口宽而容器窄，媒体查询永不触发</li><li><strong>无 logo 时不渲染占位</strong>（0.3.0 起）：此前无 <code>logoUrl</code> 会渲染一个 25px 灰色空圆，属纯噪音</li></ul>',21)])])}const u=t(r,[["render",s]]);export{g as __pageData,u as default};
